ovl_intro_end:		; the end of its code; page variables follow
ovl_intro_vsize	equ 0		; its page variables; its local memory is the rest, to #8000
			IF ovl_intro_vsize > 0
			ds ovl_intro_vsize, 0
			ENDIF
